//! The Mapping `convert_to` finds between two SkyFrames, checked against the
//! C library for every pair of celestial coordinate systems.
//!
//! `sky_convert_oracle/cases.rs` is generated by
//! `tools/oracle_fixtures/sky_convert_probe.c`, which calls `astConvert`
//! between SkyFrames that differ in Epoch, Equinox and observer position,
//! with the destination Frame's AlignSystem unset and set to each system
//! that changes which conversion steps `MakeSkyMapping` (skyframe.c:5956)
//! includes, and transforms three points with the result.

// Generated; formatted by its generator rather than rustfmt.
#[rustfmt::skip]
#[path = "sky_convert_oracle/cases.rs"]
mod cases;

use starlink_ast::frames::{FrameRef, FrameSearch, SkyFrame, SkySystem};

fn convert(
    config: usize,
    from_sys: &str,
    to_sys: &str,
    align: Option<&str>,
) -> Option<Vec<[f64; 2]>> {
    let mut from = sky(from_sys, cases::FROM_PROPS[config]);
    let mut to = sky(to_sys, cases::TO_PROPS[config]);
    if let Some(a) = align {
        to.set_align_system(SkySystem::parse(a).expect("known system"));
    }
    let fs = from.convert_to(&mut to, &[]).unwrap()?;
    let map = fs.mapping(FrameRef::Base, FrameRef::Current).unwrap();
    let xin: Vec<f64> = cases::POINTS.iter().map(|p| p[0]).collect();
    let yin: Vec<f64> = cases::POINTS.iter().map(|p| p[1]).collect();
    let (xout, yout) = map.tran2(&xin, &yin, true).unwrap();
    Some(xout.iter().zip(&yout).map(|(&x, &y)| [x, y]).collect())
}

fn sky(system: &str, props: [f64; 4]) -> SkyFrame {
    let mut f = SkyFrame::unset_system();
    f.set_system(SkySystem::parse(system).expect("known system"));
    f.set_epoch_mjd(props[0]);
    f.set_equinox_mjd(props[1]);
    f.set_obs_lat(props[2]);
    f.set_obs_lon(props[3]);
    f
}

#[test]
fn convert_matches_the_c_library() {
    let mut failures = Vec::new();
    for &(config, from_sys, to_sys, align, expected) in cases::CASES {
        let label = format!("config {config} {from_sys} -> {to_sys} align {align:?}");
        let got = convert(config, from_sys, to_sys, align);
        match (got, expected) {
            (None, None) => {}
            (Some(_), None) => failures.push(format!("{label}: converts, C finds no conversion")),
            (None, Some(_)) => failures.push(format!("{label}: no conversion, C converts")),
            (Some(got), Some(want)) => {
                if !crate::common::c_values_eq(got.as_flattened(), want.as_flattened()) {
                    failures.push(format!("{label}: got {got:?}, C gives {want:?}"));
                }
            }
        }
    }
    assert!(
        failures.is_empty(),
        "{} of {} cases differ from C:\n{}",
        failures.len(),
        cases::CASES.len(),
        failures.join("\n")
    );
}
